changeSet.sql:
IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = 'api' AND TABLE_NAME = 'ExecutionAssetDataProfileSample') BEGIN CREATE TABLE [api].[ExecutionAssetDataProfileSample]( [ID] int identity(1,1) NOT NULL, [ExecutionID] [uniqueidentifier] NOT NULL, [ItemNumber] [int] NOT NULL, [ExecutionItemUid] [uniqueidentifier] NULL, [SampleType] NVARCHAR(100) NOT NULL, [Key] NVARCHAR(200) NULL, [Value] NVARCHAR(200) NULL, [JsonValue] NVARCHAR(MAX) NULL CONSTRAINT [PK_ExecutionAssetDataProfileSample] PRIMARY KEY CLUSTERED (ID) WITH (STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF) ON [PRIMARY] ) ON [PRIMARY] END
ALTER TABLE [api].[ExecutionAssetDataProfileSample] alter column Value NVARCHAR(200) null;
IF COL_LENGTH('api.ExecutionAssetDataProfileSample','JsonValue') IS NULL BEGIN ALTER TABLE [api].[ExecutionAssetDataProfileSample] ADD JsonValue nvarchar(max) null; END
